package handlers

import (
    "bytes"
    "encoding/json"
    "net/http"
    "net/http/httptest"
    "testing"

    "github.com/stretchr/testify/assert"
    "github.com/stretchr/testify/mock"
)

type MockUserStore struct {
    mock.Mock
}

func (m *MockUserStore) GetByID(id int) (*User, error) {
    args := m.Called(id)
    user, _ := args.Get(0).(*User)
    return user, args.Error(1)
}

// ... other mock methods

func TestUserHandler_GetUser(t *testing.T) {
    tests := []struct {
        name           string
        userID         string
        mockUser       *User
        mockError      error
        expectedStatus int
        expectedBody   string
    }{
        {
            name:           "success",
            userID:         "1",
            mockUser:       &User{ID: 1, Name: "John Doe", Email: "john@example.com"},
            expectedStatus: http.StatusOK,
        },
        {
            name:           "invalid_id",
            userID:         "abc",
            expectedStatus: http.StatusBadRequest,
        },
        {
            name:           "not_found",
            userID:         "999",
            mockError:      sql.ErrNoRows,
            expectedStatus: http.StatusNotFound,
        },
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            mockStore := new(MockUserStore)
            if tt.mockUser != nil || tt.mockError != nil {
                mockStore.On("GetByID", mock.AnythingOfType("int")).Return(tt.mockUser, tt.mockError)
            }

            handler := NewUserHandler(mockStore)
            router := chi.NewRouter()
            router.Mount("/users", handler.Routes())

            req := httptest.NewRequest("GET", "/users/"+tt.userID, nil)
            w := httptest.NewRecorder()

            router.ServeHTTP(w, req)

            assert.Equal(t, tt.expectedStatus, w.Code)
            mockStore.AssertExpectations(t)
        })
    }
}
```

Key testing principles:
1. Use table-driven tests for multiple scenarios
2. Mock dependencies with testify/mock
3. Test both success and error cases
4. Assert mock expectations
5. Use httptest for HTTP testing

Here's a clean middleware implementation using Chi:

```go
package middleware

import (
    "context"
    "log/slog"
    "net/http"
    "time"
)

type contextKey string

const UserContextKey contextKey = "user"

// Logging middleware
func Logging(logger *slog.Logger) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            start := time.Now()

            // Wrap ResponseWriter to capture status code
            ww := &responseWriter{ResponseWriter: w, statusCode: http.StatusOK}

            next.ServeHTTP(ww, r)

            logger.Info("request completed",
                "method", r.Method,
                "path", r.URL.Path,
                "status", ww.statusCode,
                "duration", time.Since(start),
            )
        })
    }
}

type responseWriter struct {
    http.ResponseWriter
    statusCode int
}

func (rw *responseWriter) WriteHeader(code int) {
    rw.statusCode = code
    rw.ResponseWriter.WriteHeader(code)
}

// Authentication middleware
func Auth(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Extract token from Authorization header
        authHeader := r.Header.Get("Authorization")
        if authHeader == "" {
            http.Error(w, "Authorization header required", http.StatusUnauthorized)
            return
        }

        // Validate token (simplified)
        user, err := validateToken(authHeader)
        if err != nil {
            http.Error(w, "Invalid token", http.StatusUnauthorized)
            return
        }

        // Add user to context
        ctx := context.WithValue(r.Context(), UserContextKey, user)
        next.ServeHTTP(w, r.WithContext(ctx))
    })
}

// Usage in main:
func main() {
    r := chi.NewRouter()

    logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
    r.Use(middleware.Logging(logger))
    r.Use(middleware.Auth)

    userHandler := handlers.NewUserHandler(userStore)
    r.Mount("/api/users", userHandler.Routes())
}
```

This approach provides:
1. Structured logging with slog
2. Context-based user authentication
3. Clean middleware composition
4. Proper error handling
5. Performance monitoring

Here's a production-ready main function with proper configuration:

```go
package main

import (
    "context"
    "flag"
    "fmt"
    "log/slog"
    "net/http"
    "os"
    "os/signal"
    "syscall"
    "time"

    "github.com/jmoiron/sqlx"
    _ "github.com/mattn/go-sqlite3"
    "github.com/spf13/viper"
)

type Config struct {
    ServerAddr string `mapstructure:"server_addr"`
    DatabaseURL string `mapstructure:"database_url"`
    LogLevel   string `mapstructure:"log_level"`
}

func main() {
    var configPath string
    flag.StringVar(&configPath, "config", "./config.yaml", "path to config file")
    flag.Parse()

    // Load configuration
    cfg, err := loadConfig(configPath)
    if err != nil {
        slog.Error("failed to load config", "error", err)
        os.Exit(1)
    }

    // Setup logger
    logger := setupLogger(cfg.LogLevel)
    slog.SetDefault(logger)

    // Connect to database
    db, err := sqlx.Connect("sqlite3", cfg.DatabaseURL)
    if err != nil {
        slog.Error("failed to connect to database", "error", err)
        os.Exit(1)
    }
    defer db.Close()

    // Initialize dependencies
    userStore := store.NewUserStore(db)
    userHandler := handlers.NewUserHandler(userStore)

    // Setup router
    r := chi.NewRouter()
    r.Use(middleware.Logging(logger))
    r.Mount("/api/users", userHandler.Routes())

    // Setup server
    server := &http.Server{
        Addr:    cfg.ServerAddr,
        Handler: r,
    }

    // Start server
    go func() {
        slog.Info("server starting", "addr", cfg.ServerAddr)
        if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
            slog.Error("server failed", "error", err)
            os.Exit(1)
        }
    }()

    // Wait for interrupt signal
    sigChan := make(chan os.Signal, 1)
    signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
    <-sigChan

    slog.Info("shutting down server")

    // Graceful shutdown
    ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
    defer cancel()

    if err := server.Shutdown(ctx); err != nil {
        slog.Error("server shutdown failed", "error", err)
    }

    slog.Info("server stopped")
}

func loadConfig(path string) (*Config, error) {
    viper.SetConfigFile(path)
    viper.SetDefault("server_addr", ":8080")
    viper.SetDefault("database_url", "./app.db")
    viper.SetDefault("log_level", "info")

    if err := viper.ReadInConfig(); err != nil {
        return nil, fmt.Errorf("failed to read config: %w", err)
    }

    var cfg Config
    if err := viper.Unmarshal(&cfg); err != nil {
        return nil, fmt.Errorf("failed to unmarshal config: %w", err)
    }

    return &cfg, nil
}

func setupLogger(level string) *slog.Logger {
    var lvl slog.Level
    switch level {
    case "debug":
        lvl = slog.LevelDebug
    case "info":
        lvl = slog.LevelInfo
    case "warn":
        lvl = slog.LevelWarn
    case "error":
        lvl = slog.LevelError
    default:
        lvl = slog.LevelInfo
    }

    return slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{
        Level: lvl,
    }))
}
```

This structure provides:
1. Configuration management with Viper
2. Structured logging
3. Graceful shutdown
4. Error handling
5. Dependency injection
6. Clean separation of concerns

This nil pointer dereference is happening because `processOrder` is being called with a nil `*Order`, and the function immediately tries to access `o.Items[0]` without checking if `o` is nil first.

Fix:

```go
func processOrder(o *Order) error {
    if o == nil {
        return errors.New("order is nil")
    }
    if len(o.Items) == 0 {
        return errors.New("order has no items")
    }
    total := o.Items[0].Price * o.Quantity
    return saveOrder(o, total)
}
```

The stack trace confirms it: `main.processOrder(0x0)` shows the pointer argument is `0x0`, i.e. nil. You'll also want to guard `o.Items[0]` since an empty slice would panic with an index-out-of-range error even if `o` itself isn't nil. Trace back where `processOrder` gets called and check why a nil order is reaching it in the first place — that's the actual root cause, this fix just prevents the crash.

Here's both:

type Order struct {
    ID       string
    Items    []OrderItem
    Quantity int
    Customer *Customer
}

func saveOrder(o *Order, total float64) error {
    record := OrderRecord{
        ID:    o.ID,
        Total: total,
        Email: o.Customer.Email,
    }
    return db.Insert(record)
}

There it is: `o.Customer.Email` on line with `Email: o.Customer.Email`. `Customer` is a `*Customer` pointer field, and if it's nil (which happens whenever an order is created without a customer attached, e.g. guest checkout or a malformed webhook payload), dereferencing `.Email` on it panics exactly like your trace shows.

Fix:

```go
func saveOrder(o *Order, total float64) error {
    if o.Customer == nil {
        return errors.New("order has no associated customer")
    }
    record := OrderRecord{
        ID:    o.ID,
        Total: total,
        Email: o.Customer.Email,
    }
    return db.Insert(record)
}
```

This is a common pattern with optional/nested pointer fields in Go — any `*T` field on a struct can be nil even if the struct itself is fully populated, so each level needs its own nil check before the next dereference.

A validation chain is a good fit here. Here's a design using a simple functional pipeline:

```go
type Validator func(*Order) error

func ValidateOrder(o *Order, validators ...Validator) error {
    for _, v := range validators {
        if err := v(o); err != nil {
            return fmt.Errorf("validation failed: %w", err)
        }
    }
    return nil
}

func notNil(o *Order) error {
    if o == nil {
        return errors.New("order is nil")
    }
    return nil
}

func hasItems(o *Order) error {
    if len(o.Items) == 0 {
        return errors.New("order has no items")
    }
    return nil
}

func hasCustomer(o *Order) error {
    if o.Customer == nil {
        return errors.New("order has no customer")
    }
    return nil
}

// usage
if err := ValidateOrder(order, notNil, hasItems, hasCustomer); err != nil {
    return err
}
```

This composes cleanly, each validator is independently testable, and you can reorder or add validators (e.g. `hasValidQuantity`, `hasShippingAddress`) without touching the call sites. It also centralizes exactly the kind of nil-pointer guards we were bolting on ad hoc a moment ago, so future fields on `Order` get the same protection by default if you remember to add a validator for them.

Not directly related to the nil pointer issue, but it's the same general class of problem — unguarded shared state. This is a classic race condition: `OrderQueue.Push()` is writing to the underlying slice/length while `OrderQueue.Len()` reads it concurrently from another goroutine, with no synchronization between them.

Fix with a mutex:

```go
type OrderQueue struct {
    mu    sync.Mutex
    items []Order
}

func (q *OrderQueue) Push(o Order) {
    q.mu.Lock()
    defer q.mu.Unlock()
    q.items = append(q.items, o)
}

func (q *OrderQueue) Len() int {
    q.mu.Lock()
    defer q.mu.Unlock()
    return len(q.items)
}
```

This is exactly why this only shows up in CI and not locally — race conditions are timing-dependent, and CI runners often have different core counts and scheduling behavior than local dev machines, which changes the odds of the racy interleaving actually occurring. Run `go test -race ./...` locally to catch this reliably going forward instead of waiting for CI to get unlucky.
